    return (pg.blocks || []).filter(b => o.edit || !b.hidden).map(b => { const tag = b.type === 'footer' ? 'footer' : b.type === 'banner' ? 'div' : 'section', st = b.style || {}; return `<${tag} id="b-${b.id}" class="${b.type}-${b.variant} b-${b.type}${zebra(b)}${XC[b.type] ? ' ' + XC[b.type] + b.variant : ''}${st.bg ? ' bg-' + st.bg : ''}${st.pad ? ' pad-' + st.pad : ''}${st.sz === 'l' || st.sz === 's' ? ' sz-' + st.sz : ''}${st.al ? ' al-' + st.al : ''}${st.tint && /^#[0-9a-f]{3,8}$/i.test(st.tint) ? ' tinted' : ''}${b.hidden ? ' is-hidden' : ''}"${st.tint && /^#[0-9a-f]{3,8}$/i.test(st.tint) ? ` style="background:${st.tint};color:${contrast(st.tint, '#FFFFFF') >= 4.5 ? '#FFFFFF' : '#111111'}"` : ''}${o.edit ? ` data-block="${b.id}"` : ''}>${renderBlock(c, b, pg, o)}</${tag}>`; }).join('\n');
